-- Durable account assignments and append-only completion points.
CREATE TABLE objectives_assignment_periods (
 account_id bigint NOT NULL REFERENCES accounts(id), group_key text NOT NULL,
 period_key text NOT NULL, character_id bigint NOT NULL REFERENCES characters(id),
 level integer NOT NULL CHECK(level BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(account_id,group_key,period_key)
);
CREATE TABLE objectives_assignments (
 account_id bigint NOT NULL,group_key text NOT NULL,period_key text NOT NULL,
 definition_key text NOT NULL REFERENCES objectives_definitions(key),
 PRIMARY KEY(account_id,definition_key,period_key),
 FOREIGN KEY(account_id,group_key,period_key) REFERENCES objectives_assignment_periods
);
CREATE TABLE objectives_points (
 id bigserial PRIMARY KEY,account_id bigint NOT NULL REFERENCES accounts(id),
 source_key text NOT NULL,points integer NOT NULL CHECK(points BETWEEN 0 AND 1000000),category text NOT NULL,
 character_id bigint NOT NULL REFERENCES characters(id),level integer NOT NULL CHECK(level BETWEEN 1 AND 200),
 week_key text NOT NULL,original_week_key text NOT NULL,late_credit boolean NOT NULL DEFAULT false,occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(account_id,source_key)
);
CREATE INDEX objectives_points_week ON objectives_points(week_key,account_id);
INSERT INTO settings(name,value) VALUES
 ('objectives_assignment_counts','{"daily":2,"weekly":2,"mission":2}'::jsonb),
 ('objectives_points_weights','{"daily":20,"weekly":100,"public_hunt":100,"hourly_pvp_participation":10,"hourly_pvp_win":50,"achievement":10,"onboarding":10,"mission":20,"almanax":20}'::jsonb)
ON CONFLICT(name) DO NOTHING;
-- Retire broad/private templates without altering their earned history or versions.
INSERT INTO objectives_definition_audit(definition_key,revision,operator,definition)
SELECT key,revision,'migration185: specific assigned missions',definition FROM objectives_definitions
WHERE key LIKE 'content-v1.daily.%' OR key LIKE 'content-v1.pvp.%' OR key IN ('content-v1.weekly.challenge','content-v1.weekly.dungeons');
UPDATE objectives_definitions SET definition=jsonb_set(definition,'{enabled}','false'),revision=revision+1,updated_at=CURRENT_TIMESTAMP
WHERE key LIKE 'content-v1.daily.%' OR key LIKE 'content-v1.pvp.%' OR key IN ('content-v1.weekly.challenge','content-v1.weekly.dungeons');

