INSERT INTO objectives_assignment_periods(account_id,group_key,period_key,character_id,level)
SELECT DISTINCT ON(e.account_id,g.grp,g.period) e.account_id,g.grp,g.period,e.character_id,e.character_level
FROM objectives_events e CROSS JOIN LATERAL jsonb_array_elements(e.definitions) f
JOIN objectives_definition_versions v ON v.key=f->>'key' AND v.revision=(f->>'revision')::int
CROSS JOIN LATERAL (SELECT CASE WHEN v.definition->'schedule'->>'type' IN ('daily','weekly') THEN v.definition->'schedule'->>'type' ELSE 'mission' END AS grp,
 CASE v.definition->'schedule'->>'type' WHEN 'daily' THEN (e.occurred_at AT TIME ZONE 'America/Bogota')::date::text WHEN 'weekly' THEN date_trunc('week',e.occurred_at AT TIME ZONE 'America/Bogota')::date::text ELSE 'once' END AS period) g
WHERE e.processed_at IS NULL AND v.definition->>'kind' NOT IN ('achievement','onboarding','pvp','almanax')
ORDER BY e.account_id,g.grp,g.period,e.id ON CONFLICT DO NOTHING;
INSERT INTO objectives_assignments(account_id,group_key,period_key,definition_key)
SELECT DISTINCT e.account_id,g.grp,g.period,f->>'key'
FROM objectives_events e CROSS JOIN LATERAL jsonb_array_elements(e.definitions) f
JOIN objectives_definition_versions v ON v.key=f->>'key' AND v.revision=(f->>'revision')::int
CROSS JOIN LATERAL (SELECT CASE WHEN v.definition->'schedule'->>'type' IN ('daily','weekly') THEN v.definition->'schedule'->>'type' ELSE 'mission' END AS grp,
 CASE v.definition->'schedule'->>'type' WHEN 'daily' THEN (e.occurred_at AT TIME ZONE 'America/Bogota')::date::text WHEN 'weekly' THEN date_trunc('week',e.occurred_at AT TIME ZONE 'America/Bogota')::date::text ELSE 'once' END AS period) g
WHERE e.processed_at IS NULL AND v.definition->>'kind' NOT IN ('achievement','onboarding','pvp','almanax') ON CONFLICT DO NOTHING;
